edges = {'S': [('A', 1), ('B', 4)], 'A': [('B', 1)], 'B': [('G', 5)]}
h = {'S': 0, 'A': 4, 'B': 0, 'G': 0}


def astar(reopen):
    frontier = {'S': 0}
    closed = {}
    while frontier:
        n = min(frontier, key=lambda x: (frontier[x] + h[x], x))
        g = frontier.pop(n)
        if n == 'G':
            return g
        closed[n] = g
        for m, c in edges.get(n, []):
            if m in closed and not (reopen and g + c < closed[m]):
                continue
            if m in closed:
                del closed[m]
            if m not in frontier or g + c < frontier[m]:
                frontier[m] = g + c


print('closed', astar(False), 'reopen', astar(True))

from itertools import product

pR, pS = 0.3, 0.4
pW = {(1, 1): 0.95, (1, 0): 0.8, (0, 1): 0.7, (0, 0): 0.05}
pL = {1: 0.9, 0: 0.1}


def joint(r, s, w, l):
    p = (pR if r else 1 - pR) * (pS if s else 1 - pS)
    p *= pW[(r, s)] if w else 1 - pW[(r, s)]
    return p * (pL[w] if l else 1 - pL[w])


def prob(**fixed):
    total = 0.0
    for r, s, w, l in product((0, 1), repeat=4):
        values = {'r': r, 's': s, 'w': w, 'l': l}
        if all(values[k] == v for k, v in fixed.items()):
            total += joint(r, s, w, l)
    return total


def independent(a, b, given=None):
    given = given or {}
    pg = prob(**given)
    return abs(prob(**{a: 1, b: 1}, **given) / pg - prob(**{a: 1}, **given) / pg * prob(**{b: 1}, **given) / pg) < 1e-9


print('R,S independent, nothing observed:', independent('r', 's'))
print('R,S independent, W observed:', independent('r', 's', {'w': 1}))
print('R,S independent, only L observed:', independent('r', 's', {'l': 1}))
print('R,L independent, nothing observed:', independent('r', 'l'))
print('R,L independent, W observed:', independent('r', 'l', {'w': 1}))

from math import exp


def sig(z):
    return 1 / (1 + exp(-z))


data = [((1.0, 0.0), 1.0), ((0.0, 1.0), 0.0), ((1.0, 1.0), 1.0)]
W = [[0.5, 0.5] for _ in range(3)]
B = [0.0] * 3
V = [0.5] * 3
c = 0.0


def run(x):
    h = [sig(W[j][0] * x[0] + W[j][1] * x[1] + B[j]) for j in range(3)]
    return h, sig(sum(V[j] * h[j] for j in range(3)) + c)


def loss():
    return sum((run(x)[1] - t) ** 2 for x, t in data)


start = loss()
for _ in range(500):
    for x, t in data:
        h, a = run(x)
        do = (a - t) * a * (1 - a)
        dh = [h[j] * (1 - h[j]) * V[j] * do for j in range(3)]
        for j in range(3):
            V[j] -= 0.5 * do * h[j]
            W[j][0] -= 0.5 * dh[j] * x[0]
            W[j][1] -= 0.5 * dh[j] * x[1]
            B[j] -= 0.5 * dh[j]
        c -= 0.5 * do
print('hidden units still identical:', all(abs(W[j][k] - W[0][k]) < 1e-12 for j in range(3) for k in range(2)))
print('loss fell:', loss() < start)

