edges = {'S': [('A', 1), ('B', 2)], 'A': [('G', 3)], 'B': [('G', 3)]}


def astar_tree(h):
    frontier = [(0, 'S', ['S'])]
    removed = []
    while frontier:
        frontier.sort(key=lambda e: (e[0] + h[e[1]], e[1]))
        g, n, path = frontier.pop(0)
        removed.append(f'{n}({g + h[n]})')
        if n == 'G':
            return ' '.join(removed), ''.join(path), g
        for m, c in edges.get(n, []):
            frontier.append((g + c, m, path + [m]))


for a in (6, 3):
    print('h(A) =', a, astar_tree({'S': 3, 'A': a, 'B': 3, 'G': 0}))
